mapper.select:
SELECT /* SQL_ID: ci.sc.cm.pc.ApiCertKeyMapper.select.selectApiCertKeyList - 통신테스트 목록조회 */ A.SAAS_PRDCT_ID AS SAAS_PRDCT_ID /* 상품ID */ , B.SAAS_PRDCT_PVSN_MTH_SE_CD AS SAAS_PRDCT_PVSN_MTH_SE_CD /* 상품구분코드 */ , USCM.SF_COMM_CD_NM(SAAS_PRDCT_PVSN_MTH_SE_CD) as SAAS_PRDCT_PVSN_MTH_SE_CD_NM /* 상품구분명 */ , B.SAAS_PRDCT_TYPE_CD AS SAAS_PRDCT_TYPE_CD /* 상품유형코드 */ , USCM.SF_COMM_CD_NM(SAAS_PRDCT_TYPE_CD) as SAAS_PRDCT_TYPE_CD_NM /* 상품유형명 */ , B.SAAS_PRDCT_NM AS SAAS_PRDCT_NM /* 상품명 */ , A.SRVR_SE_CD AS SRVR_SE_CD /* 서버구분코드 */ , USCM.SF_COMM_CD_NM(SRVR_SE_CD) as SRVR_SE_CD_NM /* 서버구분명 */ , CASE /* 인증정보 발급여부 */ WHEN EXISTS ( SELECT 1 FROM USCM.TBCM_CMNC_CERT_L C WHERE C.SAAS_PRDCT_ID = A.SAAS_PRDCT_ID AND C.SRVR_SE_CD = A.SRVR_SE_CD ) THEN 'Y' ELSE 'N' END AS HAS_TEST_CERT , A.FRST_CRT_PRCR_ID /* 등록자 */ , A.FRST_CRT_DT AS FRST_CRT_DT /* 등록일자 */ FROM USCM.TBCM_CMNC_MNG_L A LEFT JOIN USCM.TBCM_SAAS_PRDCT_M B ON A.SAAS_PRDCT_ID = B.SAAS_PRDCT_ID WHERE B.USE_YN = 'Y' AND A.SRVR_SE_CD = 'A0060002'
AND B.SAAS_PRDCT_PVSN_MTH_SE_CD = #{saasPrdctPvsnMthSeCd}
AND B.SAAS_PRDCT_TYPE_CD = #{saasPrdctTypeCd}
AND A.SRVR_SE_CD = #{srvrSeCd}
AND B.SAAS_PRDCT_NM ILIKE CONCAT('%', #{saasPrdctNm}, '%')
AND EXISTS ( SELECT 1 FROM USCM.TBCM_CMNC_CERT_L D WHERE D.SAAS_PRDCT_ID = A.SAAS_PRDCT_ID AND D.SRVR_SE_CD = A.SRVR_SE_CD )
AND NOT EXISTS ( SELECT 1 FROM USCM.TBCM_CMNC_CERT_L E WHERE E.SAAS_PRDCT_ID = A.SAAS_PRDCT_ID AND E.SRVR_SE_CD = A.SRVR_SE_CD )
ORDER BY A.FRST_CRT_DT DESC
LIMIT #{pageSize} OFFSET (#{currentPage} - 1) * #{pageSize}

SELECT /* SQL_ID: ci.sc.cm.pc.ApiCertKeyMapper.select.selectApiCertKeyListCnt - 통신테스트 건수조회 */ COUNT(*) FROM USCM.TBCM_CMNC_MNG_L A LEFT JOIN USCM.TBCM_SAAS_PRDCT_M B ON A.SAAS_PRDCT_ID = B.SAAS_PRDCT_ID WHERE B.USE_YN = 'Y' AND A.SRVR_SE_CD = 'A0060002'
AND B.SAAS_PRDCT_PVSN_MTH_SE_CD = #{saasPrdctPvsnMthSeCd}
AND B.SAAS_PRDCT_TYPE_CD = #{saasPrdctTypeCd}
AND A.SRVR_SE_CD = #{srvrSeCd}
AND B.SAAS_PRDCT_NM LIKE CONCAT('%', #{saasPrdctNm}, '%')
AND EXISTS ( SELECT 1 FROM USCM.TBCM_CMNC_CERT_L D WHERE D.SAAS_PRDCT_ID = A.SAAS_PRDCT_ID AND D.SRVR_SE_CD = A.SRVR_SE_CD )
AND NOT EXISTS ( SELECT 1 FROM USCM.TBCM_CMNC_CERT_L E WHERE E.SAAS_PRDCT_ID = A.SAAS_PRDCT_ID AND E.SRVR_SE_CD = A.SRVR_SE_CD )

SELECT /* SQL_ID: ci.sc.cm.pc.ApiCertKeyMapper.select.selectSubCertKeyList - 구독 목록조회 */ A.SAAS_PRDCT_ID AS SAAS_PRDCT_ID /* 상품ID */ , A.PRDSBSC_SN AS PRDSBSC_SN /* 구독일련번호 */ , B.SAAS_PRDCT_PVSN_MTH_SE_CD AS SAAS_PRDCT_PVSN_MTH_SE_CD /* 상품구분코드 */ , USCM.SF_COMM_CD_NM(SAAS_PRDCT_PVSN_MTH_SE_CD) as SAAS_PRDCT_PVSN_MTH_SE_CD_NM /* 상품구분명 */ , B.SAAS_PRDCT_TYPE_CD AS SAAS_PRDCT_TYPE_CD /* 상품유형코드 */ , USCM.SF_COMM_CD_NM(SAAS_PRDCT_TYPE_CD) as SAAS_PRDCT_TYPE_CD_NM /* 상품유형명 */ , B.SAAS_PRDCT_NM AS SAAS_PRDCT_NM /* 상품명 */ , A.INST_USER_INTG_ID AS INST_USER_INTG_ID /* 기관사용자통합아이디 */ , A.INST_USER_SE_CD AS INST_USER_SE_CD /* 기관사용자구분코드 */ , USCM.SF_COMM_CD_NM(INST_USER_SE_CD) AS INST_USER_SE_CD_NM /* 기관사용자구분명 */ , C.INSTITUTION_NAME AS INSTITUTION_NAME /* 구독기관명 */ , CASE WHEN EXISTS ( SELECT 1 FROM USCM.TBCM_PRDSBSC_CERT_L D WHERE D.SAAS_PRDCT_ID = A.SAAS_PRDCT_ID AND D.INST_USER_INTG_ID = A.INST_USER_INTG_ID ) THEN 'Y' ELSE 'N' END AS HAS_TEST_CERT /* 인증정보발급여부 */ , A.FRST_CRT_DT AS FRST_CRT_DT /* 등록일자 */ FROM USCM.TBCM_PRDSBSC_L A LEFT JOIN USCM.TBCM_SAAS_PRDCT_M B ON B.SAAS_PRDCT_ID = A.SAAS_PRDCT_ID LEFT JOIN USCM.TBCM_INST_M C ON C.INSTITUTION_CODE = A.INST_USER_INTG_ID
AND B.USE_YN = 'Y' AND A.PRDSBSC_STTS_CD IN ('A0040001', 'A0040002', 'A0040004')
AND B.SAAS_PRDCT_PVSN_MTH_SE_CD = #{saasPrdctPvsnMthSeCd}
AND B.SAAS_PRDCT_TYPE_CD = #{saasPrdctTypeCd}
AND B.SAAS_PRDCT_NM LIKE '%' || #{saasPrdctNm} || '%'
AND C.INSTITUTION_NAME LIKE '%' || #{institutionName} || '%'
AND EXISTS ( SELECT 1 FROM USCM.TBCM_PRDSBSC_CERT_L E WHERE E.SAAS_PRDCT_ID = A.SAAS_PRDCT_ID AND E.INST_USER_INTG_ID = A.INST_USER_INTG_ID )
AND NOT EXISTS ( SELECT 1 FROM USCM.TBCM_PRDSBSC_CERT_L F WHERE F.SAAS_PRDCT_ID = A.SAAS_PRDCT_ID AND F.INST_USER_INTG_ID = A.INST_USER_INTG_ID )
ORDER BY A.FRST_CRT_DT DESC
LIMIT #{pageSize} OFFSET (#{currentPage} - 1) * #{pageSize}

mapper.insert:
INSERT /* SQL_ID: ci.sc.cm.pc.ApiCertKeyMapper.select.insertApiCertInfo - 통신테스트 인증키정보 추가 */
INTO USCM.TBCM_CMNC_CERT_L (
								SAAS_PRDCT_ID 				/* 상품ID	 */
								, SRVR_SE_CD 				/* 서버구분코드 */
								, CERT_SE_CD 				/* 인증구분코드 */
								, CMNC_CERT_SN				/* 시험인증일련번호 */
								, AUTHKEY_NM 				/* 인증키명 */
								, AUTHKEY 					/* 인증키값 */
								, FRST_CRT_PRCR_ID
								, FRST_CRT_DT
								, LAST_CHG_PRCR_ID
								, LAST_CHG_DT
							)
					 values(
								#{saasPrdctId}
								, #{srvrSeCd}
								, #{certSeCd}
								, #{cmncCertSn}
								, #{authkeyNm}
								, #{authkey}
								, #{frstCrtPrcrId}
								, TO_CHAR(CURRENT_TIMESTAMP,'YYYYMMDDHH24MISS')
								, #{lastChgPrcrId}
								, TO_CHAR(CURRENT_TIMESTAMP,'YYYYMMDDHH24MISS')
							)

mapper.update:
DELETE  /* SQL_ID: ci.sc.cm.pc.ApiCertKeyMapper.select.deleteApiCertInfo - 통신테스트 인증키정보 삭제 */
FROM USCM.TBCM_CMNC_CERT_L
WHERE 
	SAAS_PRDCT_ID = #{saasPrdctId}
AND 
	SRVR_SE_CD = #{srvrSeCd}

mapper.insert:
 INSERT /* SQL_ID: ci.sc.cm.pc.ApiCertKeyMapper.select.insertSubCertInfo - 구독 인증키정보 추가 */
 INTO USCM.TBCM_PRDSBSC_CERT_L (
									SAAS_PRDCT_ID					/* 상품ID	 */
									, INST_USER_INTG_ID				/* 기관사용자통합아이디 */
									, INST_USER_SE_CD 				/* 기관사용자구분코드 */
									, PRDSBSC_SN 					/* 구독일련번호	 */
									, PRDSBSC_CERT_SN 				/* 구독인증일련번호 */
									, AUTHKEY_NM 					/* 인증키명 */
									, AUTHKEY 						/* 인증키값 */
									, FRST_CRT_PRCR_ID
									, FRST_CRT_DT
									, LAST_CHG_PRCR_ID
									, LAST_CHG_DT
								)
						 values(
									#{saasPrdctId}
									, #{instUserIntgId}
									, #{instUserSeCd}
									, #{prdsbscSn}
									, #{prdsbscCertSn}
									, #{authkeyNm}
									, #{authkey}
									, #{frstCrtPrcrId}
									, TO_CHAR(CURRENT_TIMESTAMP,'YYYYMMDDHH24MISS') 
									, #{lastChgPrcrId}
									, TO_CHAR(CURRENT_TIMESTAMP,'YYYYMMDDHH24MISS')
								)

mapper.update:
DELETE  /* SQL_ID: ci.sc.cm.pc.ApiCertKeyMapper.select.deleteSubCertInfo - 구독 인증키정보 삭제 */
FROM USCM.TBCM_PRDSBSC_CERT_L
WHERE 
	SAAS_PRDCT_ID = #{saasPrdctId}
AND 
	INST_USER_INTG_ID = #{instUserIntgId}
AND
	INST_USER_SE_CD = #{instUserSeCd}

    INSERT /* SQL_ID: ci.sc.cm.ac.ApiCertKeyMapper.insert.createJwtKey - API인증키 등록 */
    INTO USCM.TBCM_CMNC_CERT_L (
					    			SAAS_PRDCT_ID,					/* 상품아이디 */
				                    SRVR_SE_CD,						/* 서버구분코드 */
				                    APLY_KEY, 						/* 신청키 */
				                    APLY_SRCT_KEY,					/* 신청비밀키 */
				                    JSON_WEB_TOKEN_KEY,				/* JSON웹토큰키 */
				                    CERT_KEY,						/* 인증키 (refresh_tkn) */
				                    CERT_PRGRS_STP_CD, 				/* 인증진행단계코드 	*/
				                    API_COMM_SCS_YN,				/* API통신성공여부(Y) */
				                    FRST_CRT_PRCR_ID,
				                    FRST_CRT_DT,
				                    LAST_CHG_PRCR_ID,
				                    LAST_CHG_DT
					    		)
					    VALUES (
					    			#{saasPrdctId}
					    			, #{srvrSeCd}
					    			, #{aplyKey}
					    			, #{aplySrctKey}
					    			, #{jsonWebTokenKey}
					    			, #{certKey}
					    			, #{certPrgrsStpCd}
					    			, #{apiCommScsYn}
					    			, #{frstCrtPrcrId}
					    			, NOW()
					    			, #{lastChgPrcrId}
					    			, NOW()
					    		)
